def fib_with_cache(n, cache=None):
    if cache is None:
        cache = [0, 1]
    if n < len(cache):
        return cache[n]
    cache.append(fib_with_cache(n - 1, cache) + fib_with_cache(n - 2, cache))
    return cache[n]

print(fib_with_cache(5))
print(fib_with_cache(10))

