def master_trace(n):
    cache = {}
    calls = 0
    hits = 0

    def helper(k):
        nonlocal calls, hits
        calls += 1
        if k in cache:
            hits += 1
            return cache[k]
        if k <= 1:
            result = k
        else:
            result = helper(k - 1) + helper(k - 2)
        cache[k] = result
        return result

    fib = helper(n)
    return (fib, calls, hits)
